/// <summary>
///    The <c>METTOReceiptListDP</c> class is the Report Data Provider class for the
///    <c>TO receipt list</c> report.
/// </summary>
[
    SRSReportParameterAttribute(classStr(METTOReceiptListContract))
]
public class  METTOReceiptListDP extends SrsReportDataProviderPreProcessTempDB
{
    InventTransferOrderOverviewTmp  inventTransferOrderOverviewTmp;

}

Method.Source:
/// <summary>
/// Gets data from the <c>InventTransferOrderOverviewTmp</c> temporary table.
/// </summary>
/// <returns>
/// The data from the <c>InventTransferOrderOverviewTmp</c> temporary table.
/// </returns>
[
    SRSReportDataSetAttribute(tableStr(InventTransferOrderOverviewTmp))
]
public InventTransferOrderOverviewTmp getInventTransferOrderOverviewtmp()
{
    select  inventTransferOrderOverviewTmp;
    return  inventTransferOrderOverviewTmp;
}

/// <summary>
/// Processes the report business logic.
/// </summary>
/// <remarks>
/// Provides the ability to write the report business logic. This method will be called by  at runtime.
/// The method should compute data and populate the data tables that will be returned to .
/// </remarks>
public void processReport()
{
    Query                       query;
    QueryRun                    queryRun;
    METTOReceiptListContract    contract            = this.parmDataContract() as METTOReceiptListContract;
    InventTransferTable         inventTransferTable = InventTransferTable::findRecId(contract.parmRecordId());      

    if (inventTransferTable)
    {
        // bug - 39907
        // Since this report is executed directly from the Arrival Overview Transfer Order record,
        // the user already has access to the required record. Therefore, XDS is intentionally
        // bypassed to allow printing of the report for the currently selected record.

        unchecked(uncheck::XDS)
        {
            query = new Query(queryStr(InventTransferOrderOverview));

            QueryBuildDataSource queryBuildDataSource = query.dataSourceTable(tableNum(InventTransferTable));

            // check for QueryBuildDataSource
            if (queryBuildDataSource)
            {
                QueryBuildRange queryBuildRange = queryBuildDataSource.findRange(fieldNum(InventTransferTable , TransferId));
                queryBuildRange.value(queryValue(inventTransferTable.TransferId));
            }

            queryRun = new QueryRun(query);

            while (queryRun.next())
            {
                InventTransferLine inventTransferLine = queryRun.get(tableNum(InventTransferLine));

                if (inventTransferLine.TableId == tableNum(InventTransferLine))
                {
                    InventTransferTable inventTransferTableLoc = queryRun.get(tableNum(InventTransferTable));

                    inventTransferOrderOverviewTmp.clear();
                    this.insertInventTransferOrderOverviewTmp(inventTransferLine.inventDim(), inventTransferLine, inventTransferTableLoc);
                }
            }
        }
    }        
}

/// <summary>
/// Initializes the <c>InventTransferOrderOverviewTmp</c> record.
/// </summary>
/// <param name="_inventDim">
/// The table buffer of the <c>inventDim</c> table.
/// </param>
/// <param name="_inventTransferLine">
/// The table buffer of the <c>inventTransferLine</c> table.
/// </param>
/// <param name="_inventTransferTable">
/// The table buffer of the <c>inventTransferTable</c> table.
/// </param>
protected void insertInventTransferOrderOverviewTmp(InventDim _inventDim,
                                                  InventTransferLine _inventTransferLine,
                                                  InventTransferTable _inventTransferTable)
{
    InventTable                 inventTable;
    METInventTable              metInventTable;
    METInventItemOrderSetup     metInventItemOrderSetup;

    PdsCatchWeightItem pdsCatchWeightItem = PdsCatchWeightItem::find(_inventTransferLine.ItemId);

    inventTransferOrderOverviewTmp.TransferId           = _inventTransferLine.TransferId;
    inventTransferOrderOverviewTmp.ItemId               = _inventTransferLine.ItemId;
    inventTransferOrderOverviewTmp.InventLocationIdFrom = _inventTransferTable.InventLocationIdFrom;
    inventTransferOrderOverviewTmp.QtyTransfer          = pdsCatchWeightItem.RecId ? _inventTransferLine.PdsCWQtyTransfer : _inventTransferLine.QtyTransfer;
    inventTransferOrderOverviewTmp.QtyShipped           = _inventTransferLine.QtyShipped;
    inventTransferOrderOverviewTmp.InventLocationIdTo   = _inventTransferTable.InventLocationIdTo;
    inventTransferOrderOverviewTmp.ShipDate             = _inventTransferTable.ShipDate;
    inventTransferOrderOverviewTmp.ReceiveDate          = _inventTransferTable.ReceiveDate;
    inventTransferOrderOverviewTmp.TransferStatus       = _inventTransferTable.TransferStatus;
    inventTransferOrderOverviewTmp.LocationNameFrom     = _inventTransferTable.locationNameFrom();
    inventTransferOrderOverviewTmp.LocationNameTo       = _inventTransferTable.locationNameTo();
    inventTransferOrderOverviewTmp.ItemName             = _inventTransferLine.itemName();
    inventTransferOrderOverviewTmp.LineNum              = _inventTransferLine.LineNum;              

    select firstonly inventTable
        where inventTable.ItemId == _inventTransferLine.ItemId                
            outer join metInventTable
                where metInventTable.ItemId == inventTable.ItemId;

    if (inventTable)
    {
        METReqItemTable     mETReqItemTable;
        ReqItemTable        reqItemTable;
        InventItemBarcode   inventItemBarcode;
        InventDim           inventDim;
        InventLocation      inventLoc = InventLocation::find(_inventTransferTable.InventLocationIdFrom);

        select firstonly CartonPerLayer, Layers from metInventItemOrderSetup
            where metInventItemOrderSetup.ItemId == _inventTransferLine.ItemId
                && metInventItemOrderSetup.SiteId == inventLoc.InventSiteId;

        select firstonly inventDim
            where inventDim.InventSiteId == inventLoc.InventSiteId
        join reqItemTable
            where reqItemTable.ItemId == _inventTransferLine.ItemId
                && reqItemTable.CovInventDimId == inventDim.inventDimId;

        if (reqItemTable)
        {
            mETReqItemTable = METReqItemTable::find(reqItemTable.RecId);

            select firstonly inventItemBarcode
                where inventItemBarcode.itemId == _inventTransferLine.ItemId
                    && inventItemBarcode.METVendAccount == reqItemTable.VendId;
        }

        inventTransferOrderOverviewTmp.METTi                = metInventItemOrderSetup.CartonPerLayer;
        inventTransferOrderOverviewTmp.METHi                = metInventItemOrderSetup.Layers;
        inventTransferOrderOverviewTmp.METBottleSize        = metInventTable.BottleSize;
        inventTransferOrderOverviewTmp.METUPCGTIN           = inventItemBarcode.itemBarCode;
        inventTransferOrderOverviewTmp.METWHSLC             = mETReqItemTable.SlotLoc1Area;
        inventTransferOrderOverviewTmp.METUOM               = _inventTransferLine.UnitId;
        inventTransferOrderOverviewTmp.METSellUOM           = this.itemSellUOM(_inventTransferLine.ItemId, inventLoc.InventSiteId, inventLoc.InventLocationId);
        inventTransferOrderOverviewTmp.METCases             = this.itemConvertCases(inventTransferOrderOverviewTmp.METSellUOM, _inventTransferLine.UnitId, _inventTransferLine.ItemId, _inventTransferLine.QtyTransfer);
        inventTransferOrderOverviewTmp.METCWQty             = pdsCatchWeightItem.RecId ? _inventTransferLine.QtyTransfer : 0;

        inventTransferOrderOverviewTmp.insert();            
    }
}

/// <summary>
/// Get item cases
/// </summary>
/// <param name = "_sellUOM">UnitOfMeasureSymbol</param>
/// <param name = "_unitId">UnitOfMeasureSymbol</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_qty">Qty</param>
/// <returns>Qty</returns>
public Qty itemConvertCases(UnitOfMeasureSymbol _sellUOM, UnitOfMeasureSymbol _unitId, ItemId _itemId, Qty _qty)
{
    real    sellUOMQty  = 0;
    real    cases       = 0;
    real    factor      = 0;        

    if (_sellUOM == _unitId)
    {
        return _qty;
    }
    EcoResReleasedProductUnitConverter  ecoResReleasedProductUnitConverter = EcoResReleasedProductUnitConverter::construct();

    factor = ecoResReleasedProductUnitConverter.convertGivenUnitSymbols(1, _sellUOM, _unitId, NoYes::Yes, _itemId);

    sellUOMQty = _qty / factor;

    cases = ecoResReleasedProductUnitConverter.convertGivenUnitSymbols(sellUOMQty, _sellUOM, METConstants::unitcase, NoYes::Yes, _itemId);

    return cases;
}

/// <summary>
/// Get sell UOM
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_inventSiteId">InventSiteId</param>
/// <param name = "_inventLocationId">InventLocationId</param>
/// <returns>UnitOfMeasureSymbol</returns>
public UnitOfMeasureSymbol itemSellUOM(ItemId _itemId, InventSiteId _inventSiteId, InventLocationId _inventLocationId)
{
    InventDim                   inventDim;
    InventItemSalesSetup        inventItemSalesSetup;
    UnitOfMeasureSymbol         ret = '';

    if (_itemId)
    {           
        select firstonly inventItemSalesSetup
            where inventItemSalesSetup.ItemId == _itemId
        exists join inventDim
            where inventItemSalesSetup.InventDimId == inventDim.inventDimId
                && inventDim.InventSiteId == _inventSiteId;

        if (inventItemSalesSetup.METSalesUnit)
        {
            ret = inventItemSalesSetup.METSalesUnit;
        }
        else if (!inventItemSalesSetup.METSalesUnit && !ret)
        {
            inventItemSalesSetup = InventItemSalesSetup::find(_itemId, METConstants::AllowBlank);

            ret = inventItemSalesSetup.METSalesUnit;
        }
        else if (!ret)
        {
            InventTableModule  inventTableModule = InventTableModule::find(_itemId, ModuleInventPurchSales::Sales);

            ret = inventTableModule.UnitId;
        }
    }

    return ret;
}
